RB=np.array([[0,-1,0],[1,0,0],[0,0,1]])
def state(): return dict(zip(obs.meta['proprio']['layout'],obs.meta['proprio']['now']))
def command():
 p=state(); return np.array([p['cmd_'+s] for s in spec['action_types']['ee_pose']['layout']])
def move(right=None,left=None,rrot=None,lrot=None,rhand=None,lhand=None,seconds=2,label='move',hold=.3):
 a=command();b=a.copy()
 for side,pos,rot,hand,j,k in [('right',right,rrot,rhand,0,12),('left',left,lrot,lhand,6,18)]:
  if pos is not None: b[j:j+3]=(np.array(pos)-BASE)@RB
  if rot is not None: b[j+3:j+6]=np.array(rot)
  if hand is not None: b[k:k+6]=hand
 n=max(2,round(seconds/.05)); t=np.linspace(0,1,n);t=t*t*(3-2*t)
 A=a[None,:]+t[:,None]*(b-a)[None,:]
 for j in [3,9]:
  A[:,j:j+3]=Slerp([0,1],Rotation.from_rotvec(np.array([a[j:j+3],b[j:j+3]])))(t).as_rotvec()
 A=np.vstack([A,np.repeat(b[None,:],max(1,round(hold/.05)),axis=0)])
 np.save(OUT/f'actions_{seq:03d}.npy',A)
 return save(r.submit('ee_pose',A,cameras=cams,include_depth=True,video='none',note=label),label)

def brief():
